/* Kernel symbol table (kernel/lib/ksyms.c), generated by build.ps1 into the image (.ksyms). */
#ifndef DOS_KSYMS_H
#define DOS_KSYMS_H

#include <stdint.h>

/* Name of the kernel function containing `addr` and the offset into it, or NULL. */
const char *ksym_lookup(uint64_t addr, uint64_t *offset);
uint32_t    ksym_count(void);

#endif
